package com.riftlog.entity;

import java.util.UUID;

import org.springframework.data.domain.Persistable;

import jakarta.persistence.MappedSuperclass;
import jakarta.persistence.PostLoad;
import jakarta.persistence.PostPersist;
import jakarta.persistence.Transient;

/**
 * Base for aggregates whose UUID is generated by the client (offline phone).
 * Lets Spring Data call persist() instead of merge() for new rows, so saving
 * does not first SELECT every child row.
 */
@MappedSuperclass
public abstract class ClientIdEntity implements Persistable<UUID> {

    @Transient
    private boolean isNew = true;

    @Override
    public boolean isNew() {
        return isNew;
    }

    @PostLoad
    @PostPersist
    void markNotNew() {
        this.isNew = false;
    }
}
